#' Fragility Index for Dichotomous Outcomes
#'
#' Computes the Fragility Index (FI) and Fragility Quotient (FQ) for a 
#' two-group trial with a dichotomous (binary) outcome. The Fragility Index is 
#' the minimum number of patients whose outcome would need to change (from 
#' non-event to event, or vice versa) to reverse the statistical significance 
#' of the result. A small Fragility Index means a "significant" finding hinges 
#' on only a handful of events and should be interpreted with caution. The 
#' Fragility Quotient normalizes the index by total sample size. For a 
#' non-significant result, the reverse fragility index is reported: the number 
#' of outcome changes needed to reach significance.
#' 
#'
#' @examples
#' \donttest{
#' # From a 2x2 summary:
#' fragilityindex(
#'     dataFormat = "summary",
#'     events1 = 10, n1 = 100,
#'     events2 = 25, n2 = 100,
#'     alpha = 0.05, testType = "fisher")
#'}
#' @param data The data as a data frame (used only when dataFormat = "raw").
#' @param dataFormat Whether to enter summary 2x2 counts directly or supply
#'   raw group and outcome variables from the dataset.
#' @param group Two-level grouping variable (used when dataFormat = "raw").
#' @param outcome Two-level binary outcome variable (used when dataFormat =
#'   "raw").
#' @param outcomeEvent The level of the outcome variable that denotes the
#'   event of interest.
#' @param events1 Number of events in group 1 (dataFormat = "summary").
#' @param n1 Total number of subjects in group 1 (dataFormat = "summary").
#' @param events2 Number of events in group 2 (dataFormat = "summary").
#' @param n2 Total number of subjects in group 2 (dataFormat = "summary").
#' @param testType The test used to assess statistical significance at each
#'   step.
#' @param alpha The two-sided significance threshold.
#' @param showCounts Display the reconstructed 2x2 contingency table.
#' @param showTrajectory Display the step-by-step p-value trajectory as
#'   outcomes are reversed.
#' @param showPlot Plot the p-value against the number of outcome reversals.
#' @param showSummary Display a plain-language interpretation of the fragility
#'   index.
#' @param showExplanation Display an explanation of the fragility index
#'   methodology.
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$todo} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$countsTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$mainTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$trajectoryTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$explanation} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$countsTable$asDF}
#'
#' \code{as.data.frame(results$countsTable)}
#'
#' @export
fragilityindex <- function(
    data,
    dataFormat = "summary",
    group,
    outcome,
    outcomeEvent,
    events1 = 10,
    n1 = 100,
    events2 = 25,
    n2 = 100,
    testType = "fisher",
    alpha = 0.05,
    showCounts = TRUE,
    showTrajectory = TRUE,
    showPlot = TRUE,
    showSummary = FALSE,
    showExplanation = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("fragilityindex requires jmvcore to be installed (restart may be required)")

    if ( ! missing(group)) group <- jmvcore::resolveQuo(jmvcore::enquo(group))
    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(group), group, NULL),
            `if`( ! missing(outcome), outcome, NULL))

    for (v in group) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])
    for (v in outcome) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- fragilityindexOptions$new(
        dataFormat = dataFormat,
        group = group,
        outcome = outcome,
        outcomeEvent = outcomeEvent,
        events1 = events1,
        n1 = n1,
        events2 = events2,
        n2 = n2,
        testType = testType,
        alpha = alpha,
        showCounts = showCounts,
        showTrajectory = showTrajectory,
        showPlot = showPlot,
        showSummary = showSummary,
        showExplanation = showExplanation)

    analysis <- fragilityindexClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

